head.b:skin:
/* Modern editorial blog system */
:root {
  --font-display: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-main: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-xs: .78rem; --font-sm: .92rem; --font-base: 1rem; --font-md: 1.15rem; --font-lg: 1.45rem; --font-xl: 1.9rem; --font-2xl: clamp(2.2rem, 5vw, 3.45rem);
  --lh-tight: 1.12; --lh-snug: 1.38; --lh-normal: 1.75;
  --cartoon-border-width: 1px; --cartoon-border-color: #e6eaf0; --cartoon-border: 1px solid var(--cartoon-border-color);
  --cartoon-shadow: 0 8px 30px rgba(15,23,42,.06); --cartoon-shadow-hover: 0 18px 44px rgba(15,23,42,.12); --cartoon-radius: 20px;
  --bg-color: #f7f8fa; --card-bg: #ffffff; --card-bg-hover: #fbfcfe; --text-color: #172033; --text-muted: #687385;
  --header-bg: rgba(255,255,255,.86); --header-text: #172033; --header-accent: #315efb;
  --accent-color: #315efb; --accent-hover: #254bd0; --accent-light: #edf2ff; --accent-button-bg: #315efb; --accent-button-hover: #254bd0; --accent-button-text: #fff;
  --border-color: #e6eaf0; --border-radius: 20px; --dropdown-bg: #fff; --shadow-color: rgba(15,23,42,.08); --progress-color: #315efb; --transition-speed: .22s ease;
}
html.dark-mode-preload, body.dark-mode {
  --bg-color: #0f172a; --card-bg: #172033; --card-bg-hover: #1d2940; --text-color: #f8fafc; --text-muted: #b4bfd2;
  --header-bg: rgba(23,32,51,.88); --header-text: #f8fafc; --header-accent: #a1b4ff;
  --accent-color: #a1b4ff; --accent-hover: #c2ceff; --accent-light: rgba(161,180,255,.15); --accent-button-bg: #416dff; --accent-button-hover: #5c80ff; --accent-button-text: #fff;
  --border-color: #2d3b55; --cartoon-border-color: #2d3b55; --dropdown-bg: #172033; --shadow-color: rgba(0,0,0,.28); --progress-color: #a1b4ff;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }

body {
  font-family: var(--font-main);
  font-size: var(--font-base);
  line-height: var(--lh-normal);
  background-color: var(--bg-color);
  color: var(--text-color);
  transition: background-color 0.3s ease, color 0.3s ease;
  padding-top: 105px;
}

h1, h2, h3, h4, .blog-title, .nav-list a, .nav-dropdown-btn, .post-title-text, .share-title, .comments-title, .toc-title {
  font-family: var(--font-display);
  letter-spacing: 0.5px;
}

header, .blog-title, .nav-list a, .nav-dropdown-btn,
.dropdown-menu, .search-container, .search-btn, 
.dark-toggle, #live-search-results, .ad-banner, .post-card,
.single-post, .static-page, .comments-wrapper, .latest-post-item, 
.pager-link, #back-to-top, .toc-box, .sidebar-tabs-wrapper {
  transition: all var(--transition-speed);
}

.progress-container {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 6px;
  background: transparent;
  z-index: 10000;
}

.progress-bar {
  height: 6px;
  background: var(--progress-color);
  width: 0%;
  border-right: var(--cartoon-border);
  transition: width 0.1s ease-out;
}

.container {
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 20px;
}

header {
  position: fixed;
  top: 12px;
  left: 20px;
  right: 20px;
  max-width: 1100px;
  margin: 0 auto;
  z-index: 999;
  background-color: var(--header-bg);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: 25px;
}

.header-inner {
  padding: 10px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.blog-title {
  background-color: var(--accent-color);
  padding: 6px 16px;
  border: var(--cartoon-border);
  border-radius: 15px;
  font-weight: 700;
  font-size: var(--font-lg);
  line-height: var(--lh-snug);
  text-decoration: none;
  color: #FFFFFF !important;
  text-align: center;
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  transform: rotate(-1.5deg);
  flex: 0 1 auto;
  min-width: 0;
  max-width: min(320px, 32vw);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.blog-title:hover {
  transform: rotate(1.5deg) scale(1.05);
}

.mobile-menu-btn {
  display: none;
  background: var(--card-bg);
  border: var(--cartoon-border);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  border-radius: 12px;
  color: var(--text-color);
  font-size: var(--font-lg);
  cursor: pointer;
  padding: 5px;
  min-width: 42px;
  min-height: 42px;
  align-items: center;
  justify-content: center;
}

nav {
  display: flex;
  align-items: center;
  min-width: 0;
}

.mobile-search-wrapper { display: none; }
.desktop-search-wrapper { display: block; }

.nav-list {
  display: flex;
  list-style: none;
  gap: 12px;
  align-items: center;
}

.nav-list li { position: relative; }

.nav-list a, .nav-dropdown-btn {
  text-decoration: none;
  color: var(--header-text);
  font-weight: 700;
  padding: 8px 14px;
  border-radius: 12px;
  background: var(--card-bg);
  border: var(--cartoon-border);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  font-size: var(--font-sm);
  line-height: var(--lh-snug);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.nav-list a:hover, .nav-dropdown-btn:hover {
  background-color: var(--accent-color);
  color: #FFFFFF;
  transform: translateY(-2px);
  box-shadow: 4px 4px 0px var(--cartoon-border-color);
}

.dropdown { position: relative; }

.dropdown-menu {
  display: none;
  position: absolute;
  top: 110%;
  left: 0;
  background-color: var(--dropdown-bg);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: 16px;
  min-width: 170px;
  list-style: none;
  padding: 8px;
  z-index: 100;
}

.dropdown-menu li { width: 100%; margin-bottom: 4px; }
.dropdown-menu li:last-child { margin-bottom: 0; }

.dropdown-menu a {
  display: block;
  padding: 8px 12px;
  border-radius: 10px;
  font-size: var(--font-sm);
  line-height: var(--lh-snug);
  color: var(--text-color);
  border: none;
  box-shadow: none;
}

.dropdown-menu a:hover {
  background-color: var(--accent-color);
  color: #FFFFFF;
  transform: translateX(3px);
  box-shadow: none;
}

.dropdown:hover .dropdown-menu, .dropdown-menu.open { display: block; }

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.search-container {
  position: relative;
  display: flex;
  align-items: center;
  background: var(--card-bg);
  border: var(--cartoon-border);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  border-radius: 15px;
  padding: 2px 6px;
  height: 40px;
}

.search-input {
  border: none;
  background: transparent;
  color: var(--text-color);
  padding: 6px 8px;
  outline: none;
  font-family: inherit;
  font-weight: 600;
  font-size: var(--font-sm);
  line-height: var(--lh-snug);
  width: 120px;
}

.search-input::placeholder {
  color: var(--text-muted);
}

.search-btn {
  background: var(--accent-color);
  border: 2px solid var(--cartoon-border-color);
  border-radius: 10px;
  cursor: pointer;
  padding: 4px;
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
}

.search-btn:hover {
  transform: scale(1.08);
}

.dark-toggle {
  background: var(--accent-button-bg);
  border: var(--cartoon-border);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  cursor: pointer;
  width: 40px;
  height: 40px;
  border-radius: 15px;
  color: #FFFFFF;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dark-toggle:hover {
  transform: translateY(-2px);
  box-shadow: 4px 4px 0px var(--cartoon-border-color);
}

.live-search-results {
  display: none;
  position: absolute;
  top: 115%;
  right: 0;
  width: 280px;
  background-color: var(--dropdown-bg);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: 16px;
  padding: 10px;
  z-index: 1001;
  max-height: 300px;
  overflow-y: auto;
}

.live-search-results a {
  display: block;
  padding: 8px 12px;
  color: var(--text-color);
  text-decoration: none;
  font-size: var(--font-sm);
  font-weight: 700;
  border-radius: 8px;
  margin-bottom: 4px;
}

.live-search-results a:hover {
  background-color: var(--accent-color);
  color: #FFFFFF;
}

.live-search-results p {
  padding: 10px;
  font-size: var(--font-sm);
  color: var(--text-muted);
  margin: 0;
}

.breadcrumbs {
  font-size: var(--font-sm);
  font-weight: 700;
  line-height: var(--lh-snug);
  color: var(--text-muted);
  margin-bottom: 15px;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.breadcrumbs a {
  color: var(--accent-color);
  text-decoration: none;
  background: var(--card-bg);
  padding: 3px 10px;
  border: 2px solid var(--cartoon-border-color);
  border-radius: 10px;
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
}

.breadcrumbs a:hover { transform: translateY(-2px); }

.main-layout {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 25px;
  margin-top: 20px;
}

.ad-banner {
  background-color: var(--card-bg);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: var(--border-radius);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  margin-bottom: 25px;
  text-align: center;
  position: relative;
}

.ad-label {
  font-size: var(--font-xs);
  font-weight: 800;
  line-height: 1;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-muted);
  margin-bottom: 5px;
}

.ad-top { min-height: 90px; width: 100%; padding: 10px; }
.ad-in-article { min-height: 90px; width: 100%; margin: 20px 0; padding: 10px; }
.ad-sidebar { min-height: 250px; width: 100%; padding: 10px; position: sticky; top: 120px; }

.ad-banner > iframe,
.ad-banner > ins {
  max-width: 100%;
}

.post-card {
  display: flex;
  flex-direction: row;
  background-color: var(--card-bg);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: var(--border-radius);
  overflow: hidden;
  margin-bottom: 24px;
}

.post-card:hover {
  transform: translate(-3px, -3px);
  box-shadow: var(--cartoon-shadow-hover);
}

.post-thumb {
  flex: 0 0 220px;
  min-height: 180px;
  background-color: var(--bg-color);
  overflow: hidden;
  position: relative;
  border-right: var(--cartoon-border);
}

.post-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease, opacity 0.3s ease;
  /* Jangan sembunyikan gambar sebelum event onload: gambar yang gagal
     dimuat tidak boleh membuat area thumbnail tampak kosong. */
  opacity: 1;
}

.post-thumb img.loaded { opacity: 1; }
.post-card:hover .post-thumb img { transform: scale(1.08) rotate(1deg); }

.post-thumb-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 8px;
  font-size: var(--font-sm);
  font-weight: 700;
  color: var(--text-muted);
}

.post-card-body {
  display: flex;
  flex-direction: column;
  padding: 20px;
  flex-grow: 1;
  min-width: 0;
  justify-content: space-between;
}

.post-card-header {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.post-category-badge {
  align-self: flex-start;
  background-color: #FFD166;
  color: #1A1A1A;
  border: 2px solid var(--cartoon-border-color);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  font-size: var(--font-xs);
  font-family: var(--font-display);
  font-weight: 700;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 12px;
  line-height: 1;
}

.post-title-text {
  font-size: var(--font-md);
  font-weight: 700;
  line-height: var(--lh-snug);
  margin: 0;
  color: var(--text-color);
}

.post-card:hover .post-title-text { color: var(--accent-color); }

.post-snippet-text {
  color: var(--text-muted);
  font-size: var(--font-sm);
  line-height: var(--lh-normal);
  margin-top: 4px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.post-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 16px;
  padding-top: 12px;
  border-top: 2px dashed var(--cartoon-border-color);
  font-size: var(--font-sm);
  font-weight: 700;
  line-height: var(--lh-snug);
  color: var(--text-muted);
}

.post-card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  min-width: 0;
}

.post-read-more {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background-color: var(--accent-button-bg);
  color: var(--accent-button-text);
  border: 2px solid var(--cartoon-border-color);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  font-weight: 800;
  font-size: var(--font-xs);
  padding: 8px 16px;
  border-radius: 14px;
  text-decoration: none;
  white-space: nowrap;
  flex-shrink: 0;
}

.post-read-more:hover { 
  background-color: var(--accent-button-hover);
  transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0px var(--cartoon-border-color);
}

.single-post, .static-page {
  background-color: var(--card-bg);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  padding: 30px;
  border-radius: var(--border-radius);
  line-height: var(--lh-normal);
}

.single-post h1, .static-page h1 {
  font-size: var(--font-2xl);
  line-height: var(--lh-tight);
  font-weight: 700;
  margin-bottom: 12px;
  color: var(--text-color);
}

.post-body-content h2, .static-page-content h2 {
  font-size: var(--font-xl);
  line-height: var(--lh-snug);
  font-weight: 700;
  margin: 28px 0 14px;
  scroll-margin-top: 120px;
}

.post-body-content h3, .static-page-content h3 {
  font-size: var(--font-lg);
  line-height: var(--lh-snug);
  font-weight: 700;
  margin: 22px 0 12px;
  scroll-margin-top: 120px;
}

.post-body-content h4, .static-page-content h4 {
  font-size: var(--font-md);
  line-height: var(--lh-snug);
  font-weight: 700;
  margin: 18px 0 10px;
  scroll-margin-top: 120px;
}

.static-page-content p, .post-body-content p { margin-bottom: 1rem; }

.static-page-content ul, .static-page-content ol,
.post-body-content ul, .post-body-content ol {
  margin: 10px 0 15px 20px;
}

.post-meta {
  display: flex;
  gap: 12px;
  font-size: var(--font-sm);
  font-weight: 700;
  line-height: var(--lh-snug);
  color: var(--text-muted);
  margin-bottom: 18px;
  flex-wrap: wrap;
}

.post-meta-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-color);
  border: 2px solid var(--cartoon-border-color);
  padding: 4px 10px;
  border-radius: 10px;
}

.post-body-content { margin-top: 20px; }
.post-body-content a { color: var(--accent-color); font-weight: 800; }

.post-body-content img {
  max-width: 100% !important;
  height: auto !important;
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: 16px;
  display: block;
  margin: 20px auto;
}

.toc-box {
  background-color: var(--bg-color);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: var(--border-radius);
  padding: 18px 20px;
  margin: 25px 0 30px;
}

.toc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  user-select: none;
}

.toc-title {
  font-size: var(--font-md);
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-color);
}

.toc-toggle-btn {
  background: var(--card-bg);
  border: 2px solid var(--cartoon-border-color);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  color: var(--text-color);
  font-family: var(--font-display);
  font-size: var(--font-sm);
  font-weight: 700;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 10px;
}

.toc-toggle-btn:hover { transform: scale(1.05); }

.toc-content {
  margin-top: 14px;
  padding-top: 14px;
  border-top: 2px dashed var(--cartoon-border-color);
}

.toc-content.collapsed { display: none; }

.toc-list {
  list-style: none;
  margin: 0 !important;
  padding: 0 !important;
}

.toc-list li {
  margin-bottom: 8px;
  line-height: var(--lh-snug);
}

.toc-list li:last-child { margin-bottom: 0; }

.toc-list a {
  color: var(--text-color);
  font-weight: 700;
  text-decoration: none;
  font-size: var(--font-sm);
  display: inline-block;
}

.toc-list a:hover {
  color: var(--accent-color);
  text-decoration: underline;
}

.toc-depth-h2 { margin-left: 0; font-weight: 700; }
.toc-depth-h3 { margin-left: 18px; }
.toc-depth-h4 { margin-left: 36px; }

.share-container {
  margin-top: 30px;
  padding-top: 20px;
  border-top: 2px dashed var(--cartoon-border-color);
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.share-title { 
  font-weight: 700; 
  font-size: var(--font-md);
  color: var(--text-color);
}

.share-btn {
  padding: 8px 16px;
  border-radius: 14px;
  text-decoration: none;
  font-family: var(--font-display);
  font-size: var(--font-sm);
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-color);
  background-color: var(--card-bg);
  border: var(--cartoon-border);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
}

.share-btn svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
}

.share-btn:hover {
  transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0px var(--cartoon-border-color);
}

.share-wa:hover { background-color: #25D366; color: #FFFFFF; }
.share-fb:hover { background-color: #1877F2; color: #FFFFFF; }
.share-tw:hover { background-color: #1A1A1A; color: #FFFFFF; }

.comments-wrapper {
  margin-top: 30px;
  background-color: var(--card-bg);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  padding: 25px;
  border-radius: var(--border-radius);
}

.comments-title {
  font-size: var(--font-lg);
  font-weight: 700;
  line-height: var(--lh-snug);
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ===== Styling komentar bawaan Blogger (threaded) =====
   Nama class di bawah (comment-thread, comment-replies, comment-header .user,
   comment-actions, thread-count) diambil dari struktur tema Blogger nyata yang
   masih dipakai di produksi — bukan tebakan generik lagi. [Kemungkinan Besar]
   cocok untuk mayoritas kasus; kalau ada bagian yang tidak nempel, kirim HTML
   hasil Inspect Element dari blog Anda yang sudah live, saya sesuaikan persis. */
.comments-wrapper .comments-content { margin-bottom: 16px; }
.comments-wrapper .comments-content .comment-thread { margin: 0 0 14px; }
.comments-wrapper .comments-content .comment-thread ol { list-style: none; margin: 0; padding: 0; }
.comments-wrapper .comments-content .comment-thread:empty { display: none; }

/* Kartu tiap komentar */
.comments-wrapper .comments-content .comment {
  background-color: var(--card-bg);
  border: var(--cartoon-border);
  border-radius: var(--cartoon-radius);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  padding: 14px 18px;
}

/* Header: nama + waktu */
.comments-wrapper .comment-avatar {
  width: 34px; height: 34px; border-radius: 50%; object-fit: cover; flex-shrink: 0; background: var(--bg-color);
}
.comments-wrapper .comment-header { display: flex; align-items: baseline; flex-wrap: wrap; gap: 8px; margin-bottom: 6px; }
.comments-wrapper .comment-header .user,
.comments-wrapper .comment-header .user a { font-weight: 700; font-size: var(--font-sm); color: var(--text-color); }
.comments-wrapper .comment-header .datetime,
.comments-wrapper .comment-header .datetime a { font-size: var(--font-xs); color: var(--text-muted); }

.comments-wrapper .comment-content,
.comments-wrapper .comment-body { font-size: var(--font-sm); line-height: 1.65; margin: 4px 0 8px; color: var(--text-color); }

/* Aksi: Balas / Hapus */
.comments-wrapper a.comment-reply,
.comments-wrapper a.comment-delete,
.comments-wrapper .comment-actions a,
.comments-wrapper .item-control a {
  font-size: var(--font-xs);
  font-weight: 700;
  color: var(--accent-color);
  margin-right: 14px;
  text-decoration: none;
}
.comments-wrapper a.comment-reply:hover,
.comments-wrapper a.comment-delete:hover,
.comments-wrapper .comment-actions a:hover,
.comments-wrapper .item-control a:hover { color: var(--accent-hover); text-decoration: underline; }

/* Balasan bertingkat — indentasi + garis vertikal untuk hierarki "reply terstruktur" */
.comments-wrapper .comments-content .comment-replies {
  margin-left: 34px;
  margin-top: 10px;
  padding-left: 16px;
  border-left: 2px solid var(--border-color);
}
.comments-wrapper .comments-content .inline-thread { padding-top: 6px; }

/* Kotak balas inline & tombol lihat-balasan */
.comments-wrapper .comment-replybox-thread,
.comments-wrapper .comment-replybox-single {
  margin: 10px 0 10px 34px;
  max-width: calc(100% - 34px);
}
.comments-wrapper .thread-count { font-size: var(--font-xs); font-weight: 700; color: var(--accent-color); }
.comments-wrapper .thread-arrow { display: none; } /* ikon sprite bawaan Blogger sering pecah tanpa asetnya */

.comments-wrapper #comment-post-message,
.comments-wrapper .comments h4 { font-size: var(--font-md); margin: 0 0 12px; color: var(--text-color); }

.comments-wrapper iframe { max-width: 100%; border: none; }
.comments-wrapper iframe.blogger-iframe-colorize { border-radius: var(--cartoon-radius); }

/* Trik resmi Blogger: selector berawalan pola di bawah ini di-mirror oleh
   skrip komentar Blogger ke DALAM iframe kotak balas — ini satu-satunya
   cara menembus batas iframe lintas-domain untuk styling kotak tulis. */
iframe .blogger-iframe-colorize.blogger-comment-from-post html body {
  background-color: var(--card-bg) !important;
  color: var(--text-color) !important;
  font-family: inherit !important;
}
iframe .blogger-iframe-colorize.blogger-comment-from-post html body textarea {
  background-color: var(--bg-color) !important;
  color: var(--text-color) !important;
  border: var(--cartoon-border) !important;
  border-radius: var(--cartoon-radius) !important;
  padding: 10px 12px !important;
  font-family: inherit !important;
  box-sizing: border-box !important;
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.sidebar-tabs-wrapper {
  background-color: var(--card-bg);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: var(--border-radius);
  padding: 16px;
}

.sidebar-tabs {
  display: flex;
  gap: 6px;
  background-color: var(--bg-color);
  border: var(--cartoon-border);
  border-radius: 16px;
  padding: 4px;
  margin-bottom: 16px;
}

.sidebar-tab-btn {
  flex: 1;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 8px 4px;
  border-radius: 12px;
  font-family: var(--font-display);
  font-size: var(--font-sm);
  font-weight: 700;
  line-height: var(--lh-snug);
  color: var(--text-muted);
  white-space: nowrap;
}

.sidebar-tab-btn.active {
  background-color: var(--accent-color);
  color: #FFFFFF;
  border: 2px solid var(--cartoon-border-color);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
}

.sidebar-tab-panel { display: none; }
.sidebar-tab-panel.active { display: block; }

.latest-posts-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.latest-post-item {
  display: flex;
  gap: 12px;
  align-items: center;
  text-decoration: none;
  color: var(--text-color);
  padding: 8px;
  background: var(--bg-color);
  border: 2px solid var(--cartoon-border-color);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  border-radius: 14px;
}

.latest-post-item:hover {
  transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0px var(--cartoon-border-color);
  background-color: var(--card-bg);
}

.latest-post-thumb {
  flex: 0 0 55px;
  width: 55px;
  height: 55px;
  border-radius: 10px;
  border: 2px solid var(--cartoon-border-color);
  overflow: hidden;
  background-color: var(--card-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

.latest-post-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 1;
  transition: opacity 0.3s ease;
}

.latest-post-thumb img.loaded { opacity: 1; }

.latest-post-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  flex: 1 1 auto;
}

.latest-post-title {
  font-family: var(--font-display);
  font-size: var(--font-sm);
  font-weight: 700;
  line-height: var(--lh-snug);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.latest-post-date {
  font-size: var(--font-xs);
  font-weight: 700;
  line-height: var(--lh-snug);
  color: var(--text-muted);
}

.sidebar-loading, .sidebar-empty {
  font-size: var(--font-sm);
  font-weight: 700;
  color: var(--text-muted);
  text-align: center;
  padding: 10px 0;
}

.category-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.category-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background-color: var(--bg-color);
  border: 2px solid var(--cartoon-border-color);
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
  padding: 6px 12px;
  border-radius: 14px;
  text-decoration: none;
  color: var(--text-color);
  font-family: var(--font-display);
  font-size: var(--font-sm);
  font-weight: 700;
  line-height: 1.2;
}

.category-pill:hover {
  background-color: #FFD166;
  color: #1A1A1A;
  transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0px var(--cartoon-border-color);
}

.category-pill-count {
  background-color: var(--accent-color);
  color: #FFFFFF;
  border: 1px solid var(--cartoon-border-color);
  font-size: var(--font-xs);
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 8px;
  line-height: 1;
}

.related-posts-inline {
  margin-top: 20px !important;
  margin-bottom: 20px !important;
  padding: 12px 16px;
  background: var(--bg-color);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: 14px;
  font-size: var(--font-base);
  line-height: var(--lh-snug);
  color: var(--text-color);
  display: block;
}

.related-posts-inline .related-posts-label { 
  font-family: var(--font-display);
  font-weight: 700; 
  color: var(--accent-color);
}

.related-posts-inline a {
  color: var(--text-color);
  font-weight: 700;
  text-decoration: underline;
}

.related-posts-inline a:hover {
  color: var(--accent-color);
}

footer {
  margin-top: 40px;
  padding: 25px 20px;
  background-color: var(--card-bg);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: var(--border-radius);
  text-align: center;
  font-size: var(--font-sm);
  font-weight: 700;
  line-height: var(--lh-snug);
  color: var(--text-muted);
  margin-bottom: 30px;
}

.footer-links {
  display: flex;
  justify-content: center;
  gap: 12px;
  list-style: none;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.footer-links a {
  color: var(--text-color);
  text-decoration: none;
  background: var(--bg-color);
  padding: 4px 12px;
  border: 2px solid var(--cartoon-border-color);
  border-radius: 10px;
  box-shadow: 2px 2px 0px var(--cartoon-border-color);
}

.footer-links a:hover {
  background-color: var(--accent-color);
  color: #FFFFFF;
  transform: translateY(-2px);
}

.blog-pager {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 40px;
  margin-bottom: 20px;
  padding-top: 24px;
  border-top: 2px dashed var(--cartoon-border-color);
}

.pager-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 20px;
  background-color: var(--card-bg);
  color: var(--text-color);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  border-radius: 16px;
  font-family: var(--font-display);
  font-size: var(--font-sm);
  font-weight: 700;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
}

.pager-link svg {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}

.pager-link:hover {
  background-color: var(--accent-button-bg);
  color: #FFFFFF;
  transform: translate(-3px, -3px);
  box-shadow: var(--cartoon-shadow-hover);
}

.pager-older { margin-left: auto; }
.pager-newer { margin-right: auto; }

#back-to-top {
  position: fixed;
  bottom: 25px;
  right: 25px;
  width: 48px;
  height: 48px;
  background-color: var(--accent-color);
  border: var(--cartoon-border);
  box-shadow: var(--cartoon-shadow);
  color: #FFFFFF;
  border-radius: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  z-index: 1000;
}

#back-to-top.show {
  opacity: 1;
  visibility: visible;
}

#back-to-top:hover {
  transform: translate(-2px, -2px) scale(1.05);
  box-shadow: var(--cartoon-shadow-hover);
  background-color: var(--accent-hover);
}

@media (max-width: 960px) and (min-width: 769px) {
  .blog-title {
    max-width: 24vw;
    padding-left: 10px;
    padding-right: 10px;
  }

  .nav-list { gap: 6px; }

  .nav-list a,
  .nav-dropdown-btn {
    padding-left: 8px;
    padding-right: 8px;
    font-size: var(--font-xs);
  }

  .search-input { width: 80px; }
  .header-actions { gap: 6px; }
}

@media (max-width: 768px) {
  body { padding-top: 145px; }

  header {
    top: 10px;
    left: 10px;
    right: 10px;
  }

  .header-inner { 
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    padding: 8px 12px; 
  }

  .mobile-menu-btn { display: flex; }
  .blog-title {
    text-align: center;
    padding: 4px 10px;
    font-size: var(--font-md);
    max-width: 45vw;
  }
  .header-actions { justify-self: end; min-width: 0; }
  .desktop-search-wrapper { display: none; }

  .mobile-search-wrapper {
    display: block;
    padding: 0 12px 12px;
  }

  .mobile-search-wrapper .search-input { width: 100%; color: var(--text-color); }
  .mobile-search-wrapper .search-container { 
    width: 100%; 
    background: var(--card-bg); 
  }

  nav {
    display: none; 
    position: absolute;
    top: 110%;
    left: 0;
    right: 0;
    background-color: var(--card-bg);
    border: var(--cartoon-border);
    box-shadow: var(--cartoon-shadow);
    border-radius: 20px;
    padding: 15px;
  }

  nav.active { display: block; }

  .nav-list { 
    flex-direction: column; 
    align-items: flex-start; 
    gap: 10px; 
  }

  .nav-list li, .nav-list a, .nav-dropdown-btn {
    width: 100%;
    text-align: left;
    justify-content: space-between;
  }

  .dropdown-menu { 
    position: static; 
    box-shadow: none; 
    padding-left: 10px; 
    border: none;
  }

  .main-layout { grid-template-columns: 1fr; }
  .post-card { flex-direction: column; }

  .post-thumb { 
    flex: none;
    width: 100%;
    height: auto;
    min-height: 0;
    aspect-ratio: 16 / 9;
    border-right: none;
    border-bottom: var(--cartoon-border);
  }

  .post-card-footer {
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 12px;
  }

  .post-read-more {
    margin-left: auto;
  }

  .single-post,
  .static-page {
    padding: 20px;
  }

  .toc-content:not(.collapsed) { display: block; }
  .toc-content.collapsed { display: none; }

  .single-post h1, .static-page h1 { font-size: var(--font-xl); }
  .post-body-content h2, .static-page-content h2 { font-size: var(--font-lg); }

  .blog-pager {
    flex-direction: row;
    gap: 10px;
  }

  .pager-link {
    flex: 1;
    justify-content: center;
    padding: 10px 12px;
    font-size: var(--font-xs);
  }

  .ad-sidebar { display: none; }

  #back-to-top { 
    bottom: 15px; 
    right: 15px; 
  }

  .live-search-results { left: 0; right: auto; width: 100%; }
}


/* =========================================================
   Complete modern-blog layout override
   ========================================================= */
html { scroll-padding-top: 110px; }
body { background: linear-gradient(180deg,#fff 0, var(--bg-color) 360px); padding-top: 86px; }
body.dark-mode { background: linear-gradient(180deg,#111c33 0, var(--bg-color) 360px); }
h1,h2,h3,h4,.blog-title,.nav-list a,.nav-dropdown-btn,.post-title-text,.share-title,.comments-title,.toc-title { letter-spacing: -.025em; }
.container { max-width: 1240px; padding: 0 24px; }

header { position: fixed; top: 0; left: 0; right: 0; max-width: none; border: none; border-bottom: 1px solid var(--border-color); border-radius: 0; box-shadow: none; background: var(--header-bg); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px); }
.header-inner { max-width: 1240px; min-height: 70px; margin: 0 auto; padding: 0 24px; gap: 24px; }
.blog-title { flex: 0 0 auto; max-width: none; padding: 0; background: transparent; border: 0; box-shadow: none; border-radius: 0; color: var(--text-color)!important; font-weight: 800; font-size: 1.25rem; transform: none; }
.blog-title::before { content: ''; display: inline-block; width: 10px; height: 10px; border-radius: 50%; margin-right: 8px; background: var(--accent-color); }
.blog-title:hover { color: var(--accent-color)!important; transform: none; }
nav { margin-right: auto; }
.nav-list { gap: 2px; }
.nav-list a,.nav-dropdown-btn { background: transparent; border: none; box-shadow: none; color: var(--header-text); border-radius: 9px; font-weight: 600; padding: 9px 12px; }
.nav-list a:hover,.nav-dropdown-btn:hover { background: var(--accent-light); color: var(--accent-color); box-shadow: none; transform: none; }
.dropdown-menu { top: 125%; border: var(--cartoon-border); border-radius: 14px; box-shadow: var(--cartoon-shadow); padding: 8px; }
.dropdown-menu a { border: none; box-shadow: none; border-radius: 9px; }
.dropdown-menu a:hover { background: var(--accent-light); color: var(--accent-color); transform: none; }
.header-actions { gap: 8px; }
.search-container { height: 38px; background: var(--bg-color); border: 1px solid var(--border-color); border-radius: 10px; box-shadow: none; }
.search-input { width: 150px; }
.search-btn { background: transparent; color: var(--accent-color); border: none; }
.dark-toggle,.mobile-menu-btn { width: 38px; height: 38px; border: 1px solid var(--border-color); border-radius: 10px; background: transparent; color: var(--text-color); box-shadow: none; }
.dark-toggle:hover,.mobile-menu-btn:hover { background: var(--accent-light); color: var(--accent-color); box-shadow: none; transform: none; }
.live-search-results { border: var(--cartoon-border); border-radius: 14px; box-shadow: var(--cartoon-shadow); }

.breadcrumbs { margin: 12px 0 26px; font-size: var(--font-xs); font-weight: 600; }
.breadcrumbs a { background: transparent; padding: 0; border: 0; box-shadow: none; color: var(--accent-color); }
.main-layout { grid-template-columns: minmax(0,1fr) 310px; gap: 38px; margin-top: 0; align-items: start; }
.main-content { min-width: 0; }

.ad-banner { border: 1px dashed var(--border-color); box-shadow: none; border-radius: 14px; background: transparent; margin-bottom: 28px; }
.ad-top,.ad-in-article { min-height: 100px; }
.ad-sidebar { min-height: 250px; }

.post-card { display: grid; grid-template-columns: 260px minmax(0,1fr); margin: 0; padding: 0; border: none; border-bottom: 1px solid var(--border-color); border-radius: 0; box-shadow: none; background: transparent; overflow: visible; }
.post-card + .post-card { margin-top: 28px; padding-top: 28px; }
.post-card:hover { transform: none; box-shadow: none; }
.post-thumb { width: 100%; min-height: 0; height: auto; aspect-ratio: 16/10; flex: none; border: none; border-radius: 14px; background: #eaf0f8; overflow: hidden; }
.post-thumb img { width: 100%; height: 100%; object-fit: cover; transition: transform .35s ease; }
.post-card:hover .post-thumb img { transform: scale(1.045); }
.post-card-body { padding: 4px 0 4px 22px; }
.post-card-header { gap: 9px; }
.post-category-badge { background: transparent; border: none; border-radius: 0; box-shadow: none; color: var(--accent-color); padding: 0; font-family: var(--font-main); font-size: var(--font-xs); font-weight: 800; letter-spacing: .08em; }
.post-title-text { font-size: clamp(1.25rem,2.2vw,1.55rem); line-height: 1.3; font-weight: 780; }
.post-snippet-text { -webkit-line-clamp: 2; margin-top: 3px; }
.post-card-footer { justify-content: flex-start; gap: 16px; border: none; margin-top: 10px; padding-top: 0; font-size: var(--font-xs); }
.post-card-meta { gap: 8px; }
.post-read-more { padding: 0; margin-left: 0; background: transparent; color: var(--accent-color); border: none; border-radius: 0; box-shadow: none; font-size: var(--font-xs); }
.post-read-more:hover { background: transparent; color: var(--accent-hover); box-shadow: none; transform: translateX(3px); }

.single-post,.static-page { max-width: 820px; margin: 0 auto; padding: 0; background: transparent; border: none; border-radius: 0; box-shadow: none; }
.single-post h1,.static-page h1 { max-width: 900px; font-size: var(--font-2xl); letter-spacing: -.045em; }
.post-meta { gap: 8px; margin: 16px 0 26px; }
.post-meta-item { background: transparent; border: none; padding: 0; border-radius: 0; }
.post-body-content { font-size: 1.075rem; line-height: 1.82; }
.post-body-content h2,.static-page-content h2 { font-size: clamp(1.5rem,3vw,2rem); margin-top: 2.5rem; }
.post-body-content h3,.static-page-content h3 { margin-top: 2rem; }
.post-body-content a { color: var(--accent-color); text-decoration-thickness: 1px; text-underline-offset: 3px; }
.post-body-content img { width: 100%; border: 0; border-radius: 16px; box-shadow: none; }
.toc-box { background: var(--accent-light); border: 1px solid var(--border-color); border-radius: 14px; box-shadow: none; }
.toc-content { border-top: 1px solid var(--border-color); }
.toc-toggle-btn { border: 1px solid var(--border-color); border-radius: 8px; box-shadow: none; }
.share-container { border-top: 1px solid var(--border-color); }
.share-btn { border: 1px solid var(--border-color); border-radius: 9px; box-shadow: none; }
.share-btn:hover { box-shadow: none; transform: translateY(-2px); }
.comments-wrapper { max-width: 820px; margin: 42px auto 0; padding: 0; background: transparent; border: none; border-radius: 0; box-shadow: none; }

/* Compact comment layout: applies equally to parent comments and replies */
.comments-wrapper .comments-content .comment {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  column-gap: 9px;
  row-gap: 1px;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
.comments-wrapper .comments-content .comment + .comment { margin-top: 14px; }
.comments-wrapper .comment-avatar,
.comments-wrapper .comment-avatar-fallback {
  grid-column: 1;
  grid-row: 1;
  width: 28px;
  height: 28px;
  margin-top: 1px;
  font-size: .68rem;
}
.comments-wrapper .comment-header {
  grid-column: 2;
  grid-row: 1;
  min-height: 28px;
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  line-height: 1.25;
}
.comments-wrapper .comment-header .user,
.comments-wrapper .comment-header .user a { font-size: var(--font-sm); }
.comments-wrapper .comment-header .datetime,
.comments-wrapper .comment-header .datetime a { font-size: .72rem; }
.comments-wrapper .comment-content,
.comments-wrapper .comment-body,
.comments-wrapper .deleted-comment {
  grid-column: 2;
  margin: 1px 0 0;
  font-size: var(--font-sm);
  line-height: 1.55;
}
.comments-wrapper .comment-actions,
.comments-wrapper .item-control {
  grid-column: 2;
  margin-top: 3px;
  line-height: 1.2;
}
.comments-wrapper a.comment-reply,
.comments-wrapper a.comment-delete,
.comments-wrapper .comment-actions a,
.comments-wrapper .item-control a {
  margin-right: 10px;
  font-size: .72rem;
  line-height: 1.2;
}
.comments-wrapper .comments-content .comment-replies {
  margin: 9px 0 0 18px;
  padding-left: 10px;
  border-left: 1px solid var(--border-color);
}
.comments-wrapper .comments-content .comment-replies .comment { margin-top: 10px; }
.comments-wrapper .comments-content .comment-replies .comment + .comment { margin-top: 10px; }
.comments-wrapper .comment-replybox-thread,
.comments-wrapper .comment-replybox-single {
  margin: 8px 0 8px 18px;
  max-width: calc(100% - 18px);
}
@media (max-width: 480px) {
  .comments-wrapper .comments-content .comment { grid-template-columns: 26px minmax(0, 1fr); column-gap: 8px; }
  .comments-wrapper .comment-avatar,
  .comments-wrapper .comment-avatar-fallback { width: 26px; height: 26px; }
  .comments-wrapper .comments-content .comment-replies { margin-left: 12px; padding-left: 8px; }
  .comments-wrapper .comment-replybox-thread,
  .comments-wrapper .comment-replybox-single { margin-left: 12px; max-width: calc(100% - 12px); }
}

.sidebar { position: sticky; top: 94px; gap: 20px; }
.sidebar-tabs-wrapper { border: 1px solid var(--border-color); border-radius: 16px; box-shadow: none; padding: 16px; }
.sidebar-tabs { border: none; border-radius: 10px; background: var(--bg-color); padding: 4px; }
.sidebar-tab-btn.active { border: none; border-radius: 8px; box-shadow: none; }
.latest-post-item { padding: 8px 0; border: none; border-bottom: 1px solid var(--border-color); border-radius: 0; box-shadow: none; background: transparent; }
.latest-post-item:last-child { border-bottom: none; }
.latest-post-item:hover { background: transparent; box-shadow: none; color: var(--accent-color); transform: none; }
.latest-post-thumb { width: 58px; height: 58px; flex-basis: 58px; border: none; border-radius: 9px; }
.category-pill { border: 1px solid var(--border-color); border-radius: 999px; box-shadow: none; background: transparent; }
.category-pill:hover { background: var(--accent-light); box-shadow: none; color: var(--accent-color); transform: none; }
.category-pill-count { border: none; background: var(--accent-color); }
.related-posts-inline { background: var(--accent-light); border: 1px solid var(--border-color); border-radius: 12px; box-shadow: none; }

footer { max-width: 1192px; margin: 64px auto 28px; padding: 28px 20px; border: 1px solid var(--border-color); border-radius: 16px; box-shadow: none; background: transparent; }
.footer-links a { background: transparent; border: none; box-shadow: none; }
.footer-links a:hover { background: transparent; color: var(--accent-color); transform: none; }
.blog-pager { border-top: 1px solid var(--border-color); }
.pager-link { border: 1px solid var(--border-color); border-radius: 10px; box-shadow: none; }
.pager-link:hover { background: var(--accent-color); box-shadow: none; transform: translateY(-2px); }
#back-to-top { width: 46px; height: 46px; border: none; border-radius: 50%; box-shadow: var(--cartoon-shadow); }

.skip-link { position: fixed; top: -80px; left: 16px; z-index: 10002; background: var(--accent-color); color: #fff; padding: 10px 14px; border-radius: 9px; text-decoration: none; font-weight: 700; transition: top .2s ease; }
.skip-link:focus { top: 16px; }
a:focus-visible,button:focus-visible,input:focus-visible,[tabindex]:focus-visible { outline: 3px solid rgba(49,94,251,.42); outline-offset: 3px; border-radius: 7px; }
@media (prefers-reduced-motion: reduce) { *,*::before,*::after { animation-duration: .01ms!important; transition-duration: .01ms!important; scroll-behavior: auto!important; } }

@media (max-width: 960px) and (min-width: 769px) { .main-layout { grid-template-columns: minmax(0,1fr) 270px; gap: 26px; } .post-card { grid-template-columns: 210px minmax(0,1fr); } .search-input { width: 100px; } }
@media (max-width: 768px) {
  body { padding-top: 76px; background: var(--bg-color); }
  header { top: 0; left: 0; right: 0; border-radius: 0; }
  .header-inner { min-height: 62px; padding: 0 14px; grid-template-columns: auto 1fr auto; }
  .blog-title { justify-self: center; font-size: 1.08rem; }
  nav { top: 112%; left: 12px; right: 12px; margin: 0; border: 1px solid var(--border-color); border-radius: 14px; box-shadow: var(--cartoon-shadow); }
  .mobile-search-wrapper { padding: 0 12px 12px; }
  .main-layout { display: block; }
  .sidebar { position: static; margin-top: 36px; }
  .post-card,.post-card + .post-card { display: block; margin-top: 26px; padding-top: 0; border: none; }
  .post-thumb { aspect-ratio: 16/9; border-radius: 14px; }
  .post-card-body { padding: 16px 0 0; }
  .post-card-footer { margin-top: 10px; }
  .post-read-more { margin-left: auto; }
  .single-post,.static-page { max-width: none; }
  .post-body-content { font-size: 1rem; }
  .breadcrumbs { margin-top: 4px; }
  footer { margin: 46px 14px 18px; }
}

b:includable.script:
//
(function() {
  var items = <data:post.commentJso/>;
  var msgs = <data:post.commentMsgs/>;
  var config = <data:post.commentConfig/>;
  var cursor = null;
  if (items && items.length > 0) {
    cursor = parseInt(items[items.length - 1].timestamp) + 1;
  }
  var bodyFromEntry = function(entry) {
    if (entry.gd$extendedProperty) {
      for (var k in entry.gd$extendedProperty) {
        if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
          return '<span class="deleted-comment">' + entry.content.$t + '</span>';
        }
      }
    }
    return entry.content.$t;
  };
  var parse = function(data) {
    cursor = null;
    var comments = [];
    if (data && data.feed && data.feed.entry) {
      for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
        var comment = {};
        var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
        comment.id = id ? id[2] : null;
        comment.body = bodyFromEntry(entry);
        comment.timestamp = Date.parse(entry.published.$t) + '';
        if (entry.author && entry.author.constructor === Array) {
          var auth = entry.author[0];
          if (auth) {
            comment.author = {
              name: (auth.name ? auth.name.$t : undefined),
              profileUrl: (auth.uri ? auth.uri.$t : undefined),
              avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
            };
          }
        }
        if (entry.link) {
          if (entry.link[2]) {
            comment.link = comment.permalink = entry.link[2].href;
          }
          if (entry.link[3]) {
            var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
            if (pid && pid[1]) {
              comment.parentId = pid[1];
            }
          }
        }
        comment.deleteclass = 'item-control blog-admin';
        if (entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
              comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
            } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
              comment.displayTime = entry.gd$extendedProperty[k].value;
            }
          }
        }
        comments.push(comment);
      }
    }
    return comments;
  };
  var paginator = function(callback) {
    if (hasMore()) {
      var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
      if (cursor) {
        url += '&published-min=' + new Date(cursor).toISOString();
      }
      window.bloggercomments = function(data) {
        var parsed = parse(data);
        cursor = parsed.length < 50 ? null : parseInt(parsed[parsed.length - 1].timestamp) + 1;
        callback(parsed);
        window.bloggercomments = null;
      };
      url += '&callback=bloggercomments';
      var script = document.createElement('script');
      script.type = 'text/javascript';
      script.src = url;
      document.getElementsByTagName('head')[0].appendChild(script);
    }
  };
  var hasMore = function() {
    return !!cursor;
  };
  var getMeta = function(key, comment) {
    if ('iswriter' == key) {
      var matches = !!comment.author && comment.author.name == config.authorName && comment.author.profileUrl == config.authorUrl;
      return matches ? 'true' : '';
    } else if ('deletelink' == key) {
      return config.baseUri + '/delete-comment.g?blogID=' + config.blogId + '&postID=' + comment.id;
    } else if ('deleteclass' == key) {
      return comment.deleteclass;
    }
    return '';
  };
  var replybox = null;
  var replyUrlParts = null;
  var replyParent = undefined;
  var onReply = function(commentId, domId) {
    if (replybox == null) {
      replybox = document.getElementById('comment-editor');
      if (replybox != null) {
        replybox.height = '250px';
        replybox.style.display = 'block';
        replyUrlParts = replybox.src.split('#');
      }
    }
    if (replybox && (commentId !== replyParent)) {
      replybox.src = '';
      document.getElementById(domId).insertBefore(replybox, null);
      replybox.src = replyUrlParts[0] + (commentId ? '&parentID=' + commentId : '') + '#' + replyUrlParts[1];
      replyParent = commentId;
    }
  };
  var hash = (window.location.hash || '#').substring(1);
  var startThread, targetComment;
  if (/^comment-form_/.test(hash)) {
    startThread = hash.substring('comment-form_'.length);
  } else if (/^c[0-9]+$/.test(hash)) {
    targetComment = hash.substring(1);
  }
  var configJso = { 'maxDepth': config.maxThreadDepth };
  var provider = {
    'id': config.postId,
    'data': items,
    'loadNext': paginator,
    'hasMore': hasMore,
    'getMeta': getMeta,
    'onReply': onReply,
    'rendered': true,
    'initComment': targetComment,
    'initReplyThread': startThread,
    'config': configJso,
    'messages': msgs
  };
  var render = function() {
    if (window.goog && window.goog.comments) {
      var holder = document.getElementById('comment-holder');
      window.goog.comments.render(holder, provider);
    }
  };
  if (window.goog && window.goog.comments) {
    render();
  } else {
    window.goog = window.goog || {};
    window.goog.comments = window.goog.comments || {};
    window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
    window.goog.comments.loadQueue.push(render);
  }
})();
//

body.script:
//
    function updateThemeUI(isDark) {
      var toggleBtn = document.querySelector('.dark-toggle');
      if (toggleBtn) {
        if (isDark) {
          toggleBtn.innerHTML = '<svg height="18" width="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>';
          toggleBtn.setAttribute('aria-label', 'Aktifkan mode terang');
          toggleBtn.setAttribute('title', 'Aktifkan mode terang');
        } else {
          toggleBtn.innerHTML = '<svg height="18" width="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>';
          toggleBtn.setAttribute('aria-label', 'Aktifkan mode gelap');
          toggleBtn.setAttribute('title', 'Aktifkan mode gelap');
        }
      }
    }

    function toggleDarkMode() {
      var isDark = document.body.classList.toggle('dark-mode');
      document.documentElement.classList.toggle('dark-mode-preload', isDark);
      try {
        localStorage.setItem('theme-preference', isDark ? 'dark' : 'light');
      } catch(e) {}
      updateThemeUI(isDark);
    }

    document.addEventListener('DOMContentLoaded', function() {
      var savedTheme = null;
      try {
        savedTheme = localStorage.getItem('theme-preference');
      } catch(e) {}
      if (savedTheme === 'dark') {
        document.body.classList.add('dark-mode');
        document.documentElement.classList.add('dark-mode-preload');
        updateThemeUI(true);
      } else {
        document.body.classList.remove('dark-mode');
        document.documentElement.classList.remove('dark-mode-preload');
        updateThemeUI(false);
      }
    });

    function toggleMobileMenu(btn) {
      var nav = document.querySelector('nav');
      if (nav) {
        var active = nav.classList.toggle('active');
        if (btn) {
          btn.setAttribute('aria-expanded', active ? 'true' : 'false');
        }
      }
    }

    function switchSidebarTab(btn, tab) {
      var wrap = btn.closest('.sidebar-tabs-wrapper');
      if (!wrap) return;
      var btns = wrap.querySelectorAll('.sidebar-tab-btn');
      var panels = wrap.querySelectorAll('.sidebar-tab-panel');
      for (var i = 0; i < btns.length; i++) {
        btns[i].classList.remove('active');
        btns[i].setAttribute('aria-selected', 'false');
      }
      for (var j = 0; j < panels.length; j++) {
        panels[j].classList.remove('active');
      }
      btn.classList.add('active');
      btn.setAttribute('aria-selected', 'true');
      var panel = wrap.querySelector('.sidebar-tab-panel[data-panel="' + tab + '"]');
      if (panel) panel.classList.add('active');
      if (tab === 'terbaru') {
        loadLatestSidebarPosts();
      }
    }

    var latestSidebarPostsLoaded = false;
    function loadLatestSidebarPosts() {
      if (latestSidebarPostsLoaded) return;
      latestSidebarPostsLoaded = true;
      var script = document.createElement('script');
      script.src = '/feeds/posts/summary?alt=json-in-script&max-results=6&callback=renderLatestSidebarPosts';
      script.onerror = function () {
        var container = document.getElementById('latest-posts-container');
        if (container) container.innerHTML = '<p class="sidebar-empty">Gagal memuat postingan terbaru.</p>';
      };
      document.body.appendChild(script);
    }

    function renderLatestSidebarPosts(data) {
      var container = document.getElementById('latest-posts-container');
      if (!container) return;
      container.innerHTML = '';

      if (!data.feed || !data.feed.entry || data.feed.entry.length === 0) {
        container.innerHTML = '<p class="sidebar-empty">Belum ada artikel.</p>';
        return;
      }

      var list = document.createElement('div');
      list.className = 'latest-posts-list';

      for (var i = 0; i < data.feed.entry.length; i++) {
        var entry = data.feed.entry[i];
        var title = entry.title.$t;
        var url = '';
        for (var j = 0; j < entry.link.length; j++) {
          if (entry.link[j].rel === 'alternate') {
            url = entry.link[j].href;
            break;
          }
        }

        var thumbUrl = '';
        if (entry.media$thumbnail && entry.media$thumbnail.url) {
          thumbUrl = entry.media$thumbnail.url.replace('/s72-c/', '/s96-c/');
        }

        var dateLabel = '';
        if (entry.published && entry.published.$t) {
          var d = new Date(entry.published.$t);
          if (!isNaN(d.getTime())) {
            dateLabel = d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
          }
        }

        var a = document.createElement('a');
        a.className = 'latest-post-item';
        a.href = url;

        var thumbDiv = document.createElement('div');
        thumbDiv.className = 'latest-post-thumb';
        if (thumbUrl) {
          var img = document.createElement('img');
          img.src = thumbUrl;
          img.alt = title;
          img.setAttribute('decoding', 'async');
          img.loading = 'lazy';
          img.onload = function () { this.classList.add('loaded'); };
          thumbDiv.appendChild(img);
        } else {
          thumbDiv.innerHTML = '<svg height="20" viewBox="0 0 24 24" width="20"><path d="M21 19V5c0-1.1-.9-2-2-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2zM8.5 13.5l2.5 3.01L14.5 12l4.5 6H5l3.5-4.5z" fill="currentColor"/></svg>';
        }

        var infoDiv = document.createElement('div');
        infoDiv.className = 'latest-post-info';

        var titleSpan = document.createElement('span');
        titleSpan.className = 'latest-post-title';
        titleSpan.textContent = title;
        infoDiv.appendChild(titleSpan);

        if (dateLabel) {
          var dateSpan = document.createElement('span');
          dateSpan.className = 'latest-post-date';
          dateSpan.textContent = dateLabel;
          infoDiv.appendChild(dateSpan);
        }

        a.appendChild(thumbDiv);
        a.appendChild(infoDiv);
        list.appendChild(a);
      }

      container.appendChild(list);
    }

    function toggleDropdown(el) {
      var parent = el.closest('.dropdown');
      if (!parent) return;
      var menu = parent.querySelector('.dropdown-menu');
      if (!menu) return;

      var isOpen = menu.classList.contains('open');
      var openMenus = document.querySelectorAll('.dropdown-menu.open');
      var openBtns = document.querySelectorAll('.nav-dropdown-btn[aria-expanded="true"]');

      for (var i = 0; i < openMenus.length; i++) {
        openMenus[i].classList.remove('open');
      }
      for (var k = 0; k < openBtns.length; k++) {
        openBtns[k].setAttribute('aria-expanded', 'false');
      }

      if (!isOpen) {
        menu.classList.add('open');
        el.setAttribute('aria-expanded', 'true');
      }
    }

    document.addEventListener('click', function(e) {
      if (!e.target.closest('.dropdown')) {
        var openMenus = document.querySelectorAll('.dropdown-menu.open');
        var openBtns = document.querySelectorAll('.nav-dropdown-btn[aria-expanded="true"]');
        for (var i = 0; i < openMenus.length; i++) {
          openMenus[i].classList.remove('open');
        }
        for (var k = 0; k < openBtns.length; k++) {
          openBtns[k].setAttribute('aria-expanded', 'false');
        }
      }
      if (!e.target.closest('nav') && !e.target.closest('.mobile-menu-btn')) {
        var nav = document.querySelector('nav');
        var mobileBtn = document.querySelector('.mobile-menu-btn');
        if (nav) nav.classList.remove('active');
        if (mobileBtn) mobileBtn.setAttribute('aria-expanded', 'false');
      }
    });

    function scrollToTop() {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    var searchTimer;
    var currentSearchContainerId = 'live-search-results';
    var searchRequestId = 0;
    var activeSearchScript = null;

    function doLiveSearch(target) {
      clearTimeout(searchTimer);
      currentSearchContainerId = (target === 'mobile') ? 'live-search-results-mobile' : 'live-search-results';

      var inputId = (target === 'mobile') ? 'search-input-mobile' : 'search-input';
      var inputElem = document.getElementById(inputId);
      if (!inputElem) return;

      var query = inputElem.value.trim();
      var resultsContainer = document.getElementById(currentSearchContainerId);

      if (query.length < 2) {
        if (resultsContainer) {
          resultsContainer.style.display = 'none';
          resultsContainer.innerHTML = '';
        }
        return;
      }

      searchTimer = setTimeout(function() {
        if (activeSearchScript && activeSearchScript.parentNode) {
          activeSearchScript.parentNode.removeChild(activeSearchScript);
        }
        var thisRequestId = ++searchRequestId;
        var script = document.createElement('script');
        script.src = '/feeds/posts/summary?alt=json-in-script&q=' + encodeURIComponent(query) + '&max-results=5&callback=showSearchResults';
        script.setAttribute('data-request-id', thisRequestId);
        activeSearchScript = script;
        document.body.appendChild(script);
      }, 300);
    }

    function showSearchResults(data) {
      var resultsContainer = document.getElementById(currentSearchContainerId);
      if (!resultsContainer) return;

      resultsContainer.innerHTML = '';

      if (data.feed && data.feed.entry && data.feed.entry.length > 0) {
        for (var i = 0; i < data.feed.entry.length; i++) {
          var entry = data.feed.entry[i];
          var title = entry.title.$t;
          var url = '';

          for (var j = 0; j < entry.link.length; j++) {
            if (entry.link[j].rel === 'alternate') {
              url = entry.link[j].href;
              break;
            }
          }

          var link = document.createElement('a');
          link.href = url;
          link.textContent = title;
          resultsContainer.appendChild(link);
        }
      } else {
        resultsContainer.innerHTML = '<p>Artikel tidak ditemukan.</p>';
      }
      resultsContainer.style.display = 'block';
    }

    document.addEventListener('click', function(e) {
      var searchContainers = document.querySelectorAll('.search-container');
      var resultsContainers = document.querySelectorAll('.live-search-results');

      var isInsideSearch = false;
      searchContainers.forEach(function(container) {
        if (container.contains(e.target)) {
          isInsideSearch = true;
        }
      });

      if (!isInsideSearch) {
        resultsContainers.forEach(function(res) {
          res.style.display = 'none';
        });
      }
    });

    window.onscroll = function() {
      var winScroll = document.body.scrollTop || document.documentElement.scrollTop;
      var height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
      var scrolled = (winScroll / height) * 100;
      var progressBar = document.getElementById("myBar");
      if (progressBar) {
        progressBar.style.width = scrolled + "%";
      }

      var topBtn = document.getElementById("back-to-top");
      if (topBtn) {
        if (winScroll > 300) {
          topBtn.classList.add("show");
        } else {
          topBtn.classList.remove("show");
        }
      }
    };

    function calculateReadingTime() {
      var postBody = document.getElementById('post-body');
      var readingTimeElem = document.getElementById('reading-time');
      if (postBody && readingTimeElem) {
        var text = postBody.innerText || postBody.textContent || '';
        var words = text.trim().split(/\s+/).filter(function(word) { return word.length > 0; });
        var wordCount = words.length;
        var minutes = Math.max(1, Math.ceil(wordCount / 200));
        var iconSvg = '<svg height="16" viewBox="0 0 24 24" width="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg> ';
        readingTimeElem.innerHTML = iconSvg + minutes + ' min baca';
      }
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', calculateReadingTime);
    } else {
      calculateReadingTime();
    }

    function generateTOC() {
      var postBody = document.getElementById('post-body');
      if (!postBody) return;

      var headings = postBody.querySelectorAll('h2, h3, h4');
      if (headings.length < 2) return;

      var tocContainer = document.createElement('div');
      tocContainer.className = 'toc-box';

      var tocHeader = document.createElement('div');
      tocHeader.className = 'toc-header';

      var tocTitle = document.createElement('div');
      tocTitle.className = 'toc-title';
      tocTitle.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg> Daftar Isi';

      var toggleBtn = document.createElement('button');
      toggleBtn.className = 'toc-toggle-btn';
      toggleBtn.innerHTML = '[ Sembunyikan ]';

      tocHeader.appendChild(tocTitle);
      tocHeader.appendChild(toggleBtn);

      var tocContent = document.createElement('div');
      var isMobileView = window.matchMedia && window.matchMedia('(max-width: 768px)').matches;
      tocContent.className = isMobileView ? 'toc-content collapsed' : 'toc-content';
      toggleBtn.innerHTML = isMobileView ? '[ Tampilkan ]' : '[ Sembunyikan ]';

      var tocList = document.createElement('ul');
      tocList.className = 'toc-list';

      headings.forEach(function(heading, index) {
        var id = heading.id || 'toc-heading-' + index;
        heading.id = id;

        var li = document.createElement('li');
        var tagName = heading.tagName.toLowerCase();
        li.className = 'toc-depth-' + tagName;

        var link = document.createElement('a');
        link.href = '#' + id;
        link.textContent = heading.textContent;

        link.addEventListener('click', function(e) {
          e.preventDefault();
          heading.scrollIntoView({ behavior: 'smooth' });
          history.pushState(null, null, '#' + id);
        });

        li.appendChild(link);
        tocList.appendChild(li);
      });

      tocContent.appendChild(tocList);
      tocContainer.appendChild(tocHeader);
      tocContainer.appendChild(tocContent);

      headings[0].parentNode.insertBefore(tocContainer, headings[0]);

      tocHeader.addEventListener('click', function() {
        var isCollapsed = tocContent.classList.toggle('collapsed');
        toggleBtn.innerHTML = isCollapsed ? '[ Tampilkan ]' : '[ Sembunyikan ]';
      });
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', generateTOC);
    } else {
      generateTOC();
    }

    document.addEventListener('DOMContentLoaded', function() {
      var postBody = document.getElementById('post-body');
      if (postBody) {
        var images = postBody.getElementsByTagName('img');
        for (var i = 0; i < images.length; i++) {
          images[i].setAttribute('loading', 'lazy');
          images[i].setAttribute('decoding', 'async');
        }
      }
    });

    function initRelatedPosts() {
      var postBody = document.getElementById('post-body');
      if (!postBody) return;

      var paragraphs = [];
      for (var i = 0; i < postBody.children.length; i++) {
        if (postBody.children[i].tagName === 'P') {
          paragraphs.push(postBody.children[i]);
        }
      }

      var maxInsertions;
      if (paragraphs.length < 3) { maxInsertions = 0; }
      else if (paragraphs.length < 6) { maxInsertions = 1; }
      else if (paragraphs.length < 9) { maxInsertions = 2; }
      else { maxInsertions = 3; }

      if (maxInsertions === 0) return;

      window.__relatedParagraphs = paragraphs;
      window.__relatedMaxInsertions = maxInsertions;
      loadRelatedPosts(false);
    }

    var relatedPostsFallbackTried = false;

    function loadRelatedPosts(forceFallback) {
      var postBody = document.getElementById('post-body');
      if (!postBody) return;

      var label = postBody.getAttribute('data-post-label');
      var useLabel = label && !forceFallback;

      var script = document.createElement('script');
      script.src = useLabel
        ? '/feeds/posts/summary/-/' + encodeURIComponent(label) + '?alt=json-in-script&max-results=10&callback=renderRelatedPosts'
        : '/feeds/posts/summary?alt=json-in-script&max-results=10&callback=renderRelatedPosts';
      document.body.appendChild(script);
    }

    function pickRandomInsertionIndexes(totalParagraphs, count) {
      var indexes = [];
      var used = {};
      for (var s = 0; s < count; s++) {
        var start = Math.floor((totalParagraphs * s) / count);
        var end = Math.floor((totalParagraphs * (s + 1)) / count) - 1;
        if (start <= 0) start = Math.min(1, totalParagraphs - 2);
        if (end >= totalParagraphs - 1) end = totalParagraphs - 2;
        if (end < start) end = start;
        var idx = start + Math.floor(Math.random() * (end - start + 1));
        while (used[idx] && idx < totalParagraphs - 2) { idx++; }
        used[idx] = true;
        indexes.push(idx);
      }
      return indexes;
    }

    function renderRelatedPosts(data) {
      var postBody = document.getElementById('post-body');
      var paragraphs = window.__relatedParagraphs;
      var maxInsertions = window.__relatedMaxInsertions;
      if (!postBody || !paragraphs || !maxInsertions) return;

      var currentUrl = postBody.getAttribute('data-post-url');
      var label = postBody.getAttribute('data-post-label');
      var entries = (data.feed && data.feed.entry) ? data.feed.entry : [];
      var seenUrls = {};
      var candidates = [];

      for (var i = 0; i < entries.length; i++) {
        var entry = entries[i];
        var url = '';
        for (var j = 0; j < entry.link.length; j++) {
          if (entry.link[j].rel === 'alternate') {
            url = entry.link[j].href;
            break;
          }
        }
        if (!url || url === currentUrl || seenUrls[url]) continue;
        seenUrls[url] = true;
        candidates.push({ title: entry.title.$t, url: url });
      }

      if (candidates.length === 0) {
        if (label && !relatedPostsFallbackTried) {
          relatedPostsFallbackTried = true;
          loadRelatedPosts(true);
        }
        return;
      }

      for (var k = candidates.length - 1; k > 0; k--) {
        var r = Math.floor(Math.random() * (k + 1));
        var tmp = candidates[k]; candidates[k] = candidates[r]; candidates[r] = tmp;
      }

      var picks = candidates.slice(0, Math.min(maxInsertions, candidates.length));
      var positions = pickRandomInsertionIndexes(paragraphs.length, picks.length);

      for (var p = 0; p < picks.length; p++) {
        var targetParagraph = paragraphs[positions[p]];
        if (!targetParagraph || !targetParagraph.parentNode) continue;

        var inline = document.createElement('p');
        inline.className = 'related-posts-inline';
        var labelSpan = document.createElement('span');
        labelSpan.className = 'related-posts-label';
        labelSpan.textContent = 'Baca juga: ';
        var a = document.createElement('a');
        a.href = picks[p].url;
        a.textContent = picks[p].title;
        inline.appendChild(labelSpan);
        inline.appendChild(a);

        targetParagraph.parentNode.insertBefore(inline, targetParagraph.nextSibling);
      }
    }

    document.addEventListener('DOMContentLoaded', initRelatedPosts);
  //
